459	async function handleRequest(config, method, params, session, downstreamWs) {
460	  switch (method) {
461	    case "initialize":
462	      return {
463	        userAgent: `codex_dock_relay/${RELAY_VERSION} (${os.type()} ${os.release()}; ${os.arch()})`,
464	        codexHome: config.codexHome || process.env.CODEX_HOME || path.join(os.homedir(), ".codex"),
465	        platformFamily: "unix",
466	        platformOs: platformOs(),
467	        relayInstanceID: config.hostId,
468	      };
469	    case "thread/list":
470	      return aggregateThreadList(config, params || {});
471	    case "thread/search":
472	      return aggregateThreadSearch(config, params || {});
473	    case "thread/goal/get":
474	      return aggregateThreadGoalGet(config, params || {});
475	    case DOCK_SUBSCRIBE_METHOD:
476	      return relayStateEngineForConfig(config).subscribeDock({ session, downstreamWs, sendJson });
477	    case DOCK_RESYNC_METHOD:
478	      return relayStateEngineForConfig(config).resyncDock({ downstreamWs, sendJson });
479	    case ARCHIVE_SUBSCRIBE_METHOD:
480	      return relayStateEngineForConfig(config).subscribeArchive({ session, downstreamWs, sendJson });
481	    case ARCHIVE_RESYNC_METHOD:
482	      return relayStateEngineForConfig(config).resyncArchive({ downstreamWs, sendJson });
483	    case "relay/state/snapshot":
484	      return buildRelayStateSnapshot(config, params || {});
485	    case "thread/loaded/list":
486	      return aggregateLoadedList(config, params || {});
487	    case "thread/read":
488	      return aggregateThreadRead(config, params || {});
489	    case "thread/turns/list":
490	      return listThreadTurns(config, params || {});
491	    case "thread/resume":
492	      return resumeThread(config, params || {}, session, downstreamWs);
493	    case "thread/archive":
494	    {
495	      const result = await archiveThread(config, params || {});
496	      await relayStateEngineForConfig(config).handleArchiveMutation({
497	        threadId: params?.threadId,
498	        archived: true,
499	      });
500	      return result;
501	    }
502	    case "thread/unarchive":
503	    {
504	      const result = await unarchiveThread(config, params || {});
505	      await relayStateEngineForConfig(config).handleArchiveMutation({
506	        threadId: params?.threadId,
507	        archived: false,
508	      });
509	      return result;
510	    }
511	    case "state/query":
512	      return relayStateEngineForConfig(config).snapshotForView(params?.view || "dock", params || {});
513	    case "audio/transcription/start":
514	      return session.realtimeTranscription.start(params || {});
515	    case "audio/transcription/append":
516	      return session.realtimeTranscription.append(params || {});
517	    case "audio/transcription/commit":
518	      return session.realtimeTranscription.commit(params || {});
519	    case "audio/transcription/cancel":
520	      return session.realtimeTranscription.cancel(params || {});
521	    case "turn/start":
522	    case "turn/steer":
523	    case "turn/interrupt":
524	      return forwardToActiveUpstream(config, session, method, params || {});
525	    default:
526	      throw Object.assign(new Error(`unsupported method: ${method}`), {
527	        code: -32601,
528	      });
529	  }
530	}
