  8	struct ThreadCardStreamSnapshotCollector: Sendable {
  9	    let expectedView: ThreadCardStreamView
 10	    let timeout: Duration
 11	
 12	    init(
 13	        expectedView: ThreadCardStreamView,
 14	        timeout: Duration = CodexDockConstants.AppServer.defaultRequestTimeout
 15	    ) {
 16	        self.expectedView = expectedView
 17	        self.timeout = timeout
 18	    }
 19	
 20	    func collect(from connection: any ThreadCardStreamConnection) async throws -> ThreadCardSnapshotCollection {
 21	        try await withThrowingTaskGroup(of: ThreadCardSnapshotCollection.self) { group in
 22	            group.addTask {
 23	                try await collectWithoutTimeout(from: connection, expectedView: expectedView)
 24	            }
 25	            group.addTask {
 26	                try await Task.sleep(for: timeout)
 27	                throw DockRequestFailure.error("Timed out waiting for \(expectedView.rawValue) card stream to complete")
 28	            }
 29	
 30	            guard let collection = try await group.next() else {
 31	                throw DockRequestFailure.error("Card stream ended before returning a snapshot")
 32	            }
 33	            group.cancelAll()
 34	            return collection
 35	        }
 36	    }
 37	}
 38	
 39	private func collectWithoutTimeout(
 40	    from connection: any ThreadCardStreamConnection,
 41	    expectedView: ThreadCardStreamView
 42	) async throws -> ThreadCardSnapshotCollection {
 43	    var hostsByID: [String: DockStreamHostDTO] = [:]
 44	    var cardsByID: [String: DockThreadCardDTO] = [:]
 45	    let snapshot = try await connection.subscribe()
 46	    try apply(
 47	        snapshot,
 48	        expectedView: expectedView,
 49	        hostsByID: &hostsByID,
 50	        cardsByID: &cardsByID
 51	    )
 52	    if isComplete(snapshot) {
 53	        return ThreadCardSnapshotCollection(hosts: sortedHosts(hostsByID), cards: sortedCards(cardsByID))
 54	    }
 55	
 56	    for try await update in connection.updates() {
 57	        try apply(
 58	            update,
 59	            expectedView: expectedView,
 60	            hostsByID: &hostsByID,
 61	            cardsByID: &cardsByID
 62	        )
 63	        if isComplete(update) {
 64	            return ThreadCardSnapshotCollection(hosts: sortedHosts(hostsByID), cards: sortedCards(cardsByID))
 65	        }
 66	    }
 67	
 68	    throw DockRequestFailure.error("Card stream closed before \(expectedView.rawValue) snapshot completed")
 69	}
 70	
 71	private func apply(
 72	    _ update: ThreadCardStreamUpdateDTO,
 73	    expectedView: ThreadCardStreamView,
 74	    hostsByID: inout [String: DockStreamHostDTO],
 75	    cardsByID: inout [String: DockThreadCardDTO]
 76	) throws {
 77	    guard update.schemaVersion == CodexDockConstants.Dock.streamSchemaVersion,
 78	          update.view == expectedView else {
 79	        throw DockRequestFailure.error("Unexpected \(expectedView.rawValue) card stream contract")
 80	    }
 81	
 82	    switch update.kind {
 83	    case .snapshot:
 84	        hostsByID = Dictionary(uniqueKeysWithValues: (update.hosts ?? []).map { ($0.id, $0) })
 85	        cardsByID = Dictionary(uniqueKeysWithValues: (update.cards ?? [])
 86	            .filter(\.isAppFacingHumanThreadCard)
 87	            .map { ($0.id, $0) })
 88	    case .delta:
 89	        for host in update.upsertHosts ?? [] {
 90	            hostsByID[host.id] = host
 91	        }
 92	        for card in (update.upsertCards ?? []).filter(\.isAppFacingHumanThreadCard) {
 93	            cardsByID[card.id] = card
 94	        }
 95	        for cardID in update.deleteCardIDs ?? [] {
 96	            cardsByID.removeValue(forKey: cardID)
 97	        }
 98	    case .heartbeat:
 99	        break
100	    }
101	}
102	
103	private func sortedHosts(_ hostsByID: [String: DockStreamHostDTO]) -> [DockStreamHostDTO] {
104	    hostsByID.values.sorted { lhs, rhs in
105	        lhs.id < rhs.id
106	    }
107	}
108	
109	private func isComplete(_ update: ThreadCardStreamUpdateDTO) -> Bool {
110	    if update.complete == true {
111	        return true
112	    }
113	    guard update.window?.nextOffset == nil,
114	          update.totalRows != nil else {
115	        return false
116	    }
117	    // Bad relay payloads may count rejected non-human rows in totalRows. A final window still completes after filtering.
118	    return true
119	}
120	
121	private func sortedCards(_ cardsByID: [String: DockThreadCardDTO]) -> [DockThreadCardDTO] {
122	    cardsByID.values.sorted { lhs, rhs in
123	        if lhs.orderKey != rhs.orderKey {
124	            return lhs.orderKey < rhs.orderKey
125	        }
126	        return lhs.id < rhs.id
127	    }
128	}
