 13	    func loadAll(hosts: [DockHostConfiguration]) async -> [ThreadCardHostLoadOutcome] {
 14	        await withTaskGroup(of: ThreadCardHostLoadOutcome.self) { group in
 15	            for host in hosts {
 16	                group.addTask {
