 31	    private func load(host: DockHostConfiguration) async -> ThreadCardHostLoadOutcome {
 32	        let startedAt = Date()
 33	        DockLog.archive.debug("\(self.operation, privacy: .public) card stream load started host_id=\(host.id, privacy: .public)")
 34	        do {
 35	            let connection = try await streamClient.connect(to: host)
 36	            let collection: ThreadCardSnapshotCollection
 37	            do {
 38	                collection = try await ThreadCardStreamSnapshotCollector(expectedView: expectedView)
 39	                    .collect(from: connection)
 40	            } catch {
 41	                await connection.close()
 42	                throw error
 43	            }
 44	            await connection.close()
 45	            DockLog.archive.debug("\(self.operation, privacy: .public) card stream load finished host_id=\(host.id, privacy: .public) rows=\(collection.cards.count, privacy: .public) duration_ms=\(DockLog.milliseconds(since: startedAt), privacy: .public)")
 46	            return ThreadCardHostLoadOutcome(host: host, result: .success(collection))
 47	        } catch {
 48	            DockLog.archive.warning("\(self.operation, privacy: .public) card stream load failed host_id=\(host.id, privacy: .public) duration_ms=\(DockLog.milliseconds(since: startedAt), privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
 49	            return ThreadCardHostLoadOutcome(host: host, result: .failure(mapRequestFailure(error)))
 50	        }
 51	    }
